INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(264529, 18053, 6008, '<td valign="top">I like the silhouettes and the composition, but the sky seems a little unnatural and overly processed causing it to distract some from the scene.</td>', 'I like the silhouettes and the composition, but the sky seems a little unnatural and overly processed causing it to distract some from the scene.', '2003-04-14 01:17:13.000000', NULL, 1),
(264535, 18074, 2700, '<td valign="top">very oversharpend....</td>', 'very oversharpend....', '2003-04-14 01:18:14.000000', NULL, 1),
(264542, 18250, 6008, '<td valign="top">I like the silhouette at the bottom. Intially the uppermost section seemed a little dark, but it kind of grew on me. I probably would have cropped the top some to put more emphasis on the wonderful colors. Nicely captured.</td>', 'I like the silhouette at the bottom. Intially the uppermost section seemed a little dark, but it kind of grew on me. I probably would have cropped the top some to put more emphasis on the wonderful colors. Nicely captured.', '2003-04-14 01:20:32.000000', NULL, 1),
(264548, 18201, 6008, '<td valign="top">Wonderful architecture, dramatic sky, and the angle is oddly appealing. It would be interesting to see it in color, but I think the b&amp;w works well.</td>', 'Wonderful architecture, dramatic sky, and the angle is oddly appealing. It would be interesting to see it in color, but I think the b&w works well.', '2003-04-14 01:22:44.000000', NULL, 1),
(264551, 18204, 6008, '<td valign="top">Yup, it sure is a blue sky. Nice tint of blue too.</td>', 'Yup, it sure is a blue sky. Nice tint of blue too.', '2003-04-14 01:24:42.000000', NULL, 1),
(264559, 17684, 6008, '<td valign="top">The composition is great, but I love the mood of this photograph. The varying shades of blue sets the tone, but the fog just adds a whole dreamy atmosphere. It''s almost like a scene from a fairy tale. Excellent shot.</td>', 'The composition is great, but I love the mood of this photograph. The varying shades of blue sets the tone, but the fog just adds a whole dreamy atmosphere. It''s almost like a scene from a fairy tale. Excellent shot.', '2003-04-14 01:26:45.000000', NULL, 1),
(264560, 17684, 2700, '<td valign="top">cold, harsh, dam its good. 10</td>', 'cold, harsh, dam its good. 10', '2003-04-14 01:26:48.000000', NULL, 1),
(264563, 18149, 1344, '<td valign="top">"overly creative"..  Irrelevant photo without the title.</td>', '"overly creative"..  Irrelevant photo without the title.', '2003-04-14 01:27:13.000000', NULL, 1),
(264565, 17867, 3459, '<td valign="top">While it is a very nice image, it seems just a bit oversharpened.  Also composition wise, in my opinion this would have worked better in B&amp;W and with a lower shutter speed.  A very nice photograph nevertheless, good luck.</td>', 'While it is a very nice image, it seems just a bit oversharpened.  Also composition wise, in my opinion this would have worked better in B&W and with a lower shutter speed.  A very nice photograph nevertheless, good luck.', '2003-04-14 01:27:32.000000', NULL, 1),
(264567, 18151, 3459, '<td valign="top">A great composition although, seems a bit oversharpened.</td>', 'A great composition although, seems a bit oversharpened.', '2003-04-14 01:28:10.000000', NULL, 1),
(264569, 17736, 6008, '<td valign="top">I like the complimentary colour scheme of foreground and background. The composition is good, but I think the varying levels of texture really makes this shot work.</td>', 'I like the complimentary colour scheme of foreground and background. The composition is good, but I think the varying levels of texture really makes this shot work.', '2003-04-14 01:28:31.000000', NULL, 1),
(264572, 18228, 3459, '<td valign="top">Great use of patterns and a good choice to live the image in colour.  This contrasts the subject with the background well.</td>', 'Great use of patterns and a good choice to live the image in colour.  This contrasts the subject with the background well.', '2003-04-14 01:28:48.000000', NULL, 1),
(264573, 17990, 2700, '<td valign="top">if this pic wasn''t soo grainy I would give it a 10...</td>', 'if this pic wasn''t soo grainy I would give it a 10...', '2003-04-14 01:29:04.000000', NULL, 1),
(264574, 17915, 7504, '<td valign="top">This is hillarious!  I think this might even be you!</td>', 'This is hillarious!  I think this might even be you!', '2003-04-14 01:29:21.000000', NULL, 1),
(264577, 18037, 3459, '<td valign="top">A beautiful image.  A bit of a burn in the lower right part of the image though.  Great effort, good luck.</td>', 'A beautiful image.  A bit of a burn in the lower right part of the image though.  Great effort, good luck.', '2003-04-14 01:29:51.000000', NULL, 1),
(264578, 18152, 3459, '<td valign="top">Excellent composition!  Perfect execution! A 10!</td>', 'Excellent composition!  Perfect execution! A 10!', '2003-04-14 01:30:52.000000', NULL, 1),
(264579, 18049, 7869, '<td valign="top">a little dark for me, but a good one</td>', 'a little dark for me, but a good one', '2003-04-14 01:31:02.000000', NULL, 1),
(264580, 17632, 6008, '<td valign="top">Is that a plane down there? Hrm, not sure if the bottom section is to give it a reference point or not, but I''m leaning toward finding it slightly distracting. The clouds themselves are great - very dramatic. The range of colors, almost like a gradient are a nice change from the usual.</td>', 'Is that a plane down there? Hrm, not sure if the bottom section is to give it a reference point or not, but I''m leaning toward finding it slightly distracting. The clouds themselves are great - very dramatic. The range of colors, almost like a gradient are a nice change from the usual.', '2003-04-14 01:31:13.000000', NULL, 1),
(264584, 17847, 3459, '<td valign="top">WOW! This is a wonderful photograph!  I like the predominant blue, it sets the mood; the angled lines which contribute tention.  The symetry that imposes strength. A 10!</td>', 'WOW! This is a wonderful photograph!  I like the predominant blue, it sets the mood; the angled lines which contribute tention.  The symetry that imposes strength. A 10!', '2003-04-14 01:32:22.000000', NULL, 1),
(264587, 18141, 6008, '<td valign="top">I love the silky look to the water. Composition is good, lighting is good. Quite breathtaking, dont see anything wrong it.</td>', 'I love the silky look to the water. Composition is good, lighting is good. Quite breathtaking, dont see anything wrong it.', '2003-04-14 01:33:09.000000', NULL, 1),
(264588, 17963, 3459, '<td valign="top">Beautiful, I like the use of siluet in this image.</td>', 'Beautiful, I like the use of siluet in this image.', '2003-04-14 01:33:10.000000', NULL, 1),
(264590, 18246, 3459, '<td valign="top">Great colour, and a wonderful softness.  I think the softness of this image, is what making it special.</td>', 'Great colour, and a wonderful softness.  I think the softness of this image, is what making it special.', '2003-04-14 01:33:58.000000', NULL, 1),
(264592, 18118, 6008, '<td valign="top">Nice silhouette, great warm tones, and good capture on the reflection.</td>', 'Nice silhouette, great warm tones, and good capture on the reflection.', '2003-04-14 01:34:07.000000', NULL, 1),
