(264596, 17849, 6008, '<td valign="top">Interesting effect. Not sure if it was intentional due to the gloomy day, but the colours seem a little washed out.</td>', 'Interesting effect. Not sure if it was intentional due to the gloomy day, but the colours seem a little washed out.', '2003-04-14 01:36:03.000000', NULL, 1),
(264597, 18147, 3459, '<td valign="top">WOW!  Sorry can''t be more helpfull, just don''t think anything needs to be said; but WOW!</td>', 'WOW!  Sorry can''t be more helpfull, just don''t think anything needs to be said; but WOW!', '2003-04-14 01:36:06.000000', NULL, 1),
(264598, 18160, 3459, '<td valign="top">Perfect!  Nothing more needs to be said.</td>', 'Perfect!  Nothing more needs to be said.', '2003-04-14 01:36:55.000000', NULL, 1),
