(264614, 18242, 6771, '<td valign="top">Crisp focus and pleasing colors.  Great composition and DOF.</td>', 'Crisp focus and pleasing colors.  Great composition and DOF.', '2003-04-14 01:41:32.000000', NULL, 1),
(264615, 17921, 3459, '<td valign="top">Perfect, love the tonalities!</td>', 'Perfect, love the tonalities!', '2003-04-14 01:41:45.000000', NULL, 1),
