(265476, 18161, 3290, '<td valign="top">Great catch. Very photogenic subject.</td>', 'Great catch. Very photogenic subject.', '2003-04-14 12:56:59.000000', NULL, 1),
(265477, 18040, 7843, '<td valign="top">A bit of a tenuous link with wether but a nice photo all the same. Good composition and detail.</td>', 'A bit of a tenuous link with wether but a nice photo all the same. Good composition and detail.', '2003-04-14 12:57:03.000000', NULL, 1),
