(266078, 18108, 7073, '<td valign="top">Great shot... I love the rain drops adding some light to your pic!</td>', 'Great shot... I love the rain drops adding some light to your pic!', '2003-04-14 18:14:38.000000', NULL, 1),
(266079, 17920, 7461, '<td valign="top">great black and whiite photo.  Looks a bit like a southern winter.</td>', 'great black and whiite photo.  Looks a bit like a southern winter.', '2003-04-14 18:15:00.000000', NULL, 1),
