(266082, 18227, 7073, '<td valign="top">Awesome angle, great shot!</td>', 'Awesome angle, great shot!', '2003-04-14 18:15:51.000000', NULL, 1),
(266083, 17620, 7461, '<td valign="top">Is this real?</td>', 'Is this real?', '2003-04-14 18:16:23.000000', NULL, 1),
