(266124, 17705, 7073, '<td valign="top">Done very lovely!</td>', 'Done very lovely!', '2003-04-14 18:35:52.000000', NULL, 1),
(266126, 17923, 3669, '<td valign="top">This is a nice picture.  I like the mountain in the background.  Nicely focused, it shows what detail there is in the "weathered" fencing.  Some of the weedy bottom part of the picture is a little undesirable and could have been cropped out.</td>', 'This is a nice picture.  I like the mountain in the background.  Nicely focused, it shows what detail there is in the "weathered" fencing.  Some of the weedy bottom part of the picture is a little undesirable and could have been cropped out.', '2003-04-14 18:36:33.000000', NULL, 1),
(266128, 17956, 7021, '<td valign="top">Perfect, my only rating above 7 so far, 10 for this.</td>', 'Perfect, my only rating above 7 so far, 10 for this.', '2003-04-14 18:36:51.000000', NULL, 1),
