(266795, 17947, 6870, '<td valign="top">Wonderful image, but so small. There are several Forum threads that can help you make this larger. Lovely contrasts and tones. Very nice.</td>', 'Wonderful image, but so small. There are several Forum threads that can help you make this larger. Lovely contrasts and tones. Very nice.', '2003-04-15 01:10:00.000000', NULL, 1),
(266796, 17713, 4494, '<td valign="top">Nice shot.</td>', 'Nice shot.', '2003-04-15 01:10:06.000000', NULL, 1),
(266801, 17905, 6870, '<td valign="top">I love how the fence and solitary \\\"player\\\" add up to a feeling of trapped despair, caused by weather. Very nice. I hope people will take the time to look at this one closely.</td>', 'I love how the fence and solitary \\\"player\\\" add up to a feeling of trapped despair, caused by weather. Very nice. I hope people will take the time to look at this one closely.', '2003-04-15 01:12:05.000000', NULL, 1),
(266802, 18188, 3260, '<td valign="top">magnificent. 10, even if it isn''t entirely weather related.</td>', 'magnificent. 10, even if it isn''t entirely weather related.', '2003-04-15 01:12:55.000000', NULL, 1),
