(266833, 18126, 6870, '<td valign="top">Very nice point of view, and the flowered flag is a stroke of genius!</td>', 'Very nice point of view, and the flowered flag is a stroke of genius!', '2003-04-15 01:24:17.000000', NULL, 1),
(266837, 17985, 6870, '<td valign="top">The weird effects do make your communication more clear here. Good choice.</td>', 'The weird effects do make your communication more clear here. Good choice.', '2003-04-15 01:26:18.000000', NULL, 1),
