(269708, 17640, 3102, '<td valign="top">I''m afraid you lost me on this one... :(</td>', 'I''m afraid you lost me on this one... :(', '2003-04-17 16:30:56.000000', NULL, 1),
(269710, 17956, 7350, '<td valign="top">Wow.  Is this from a plane or something?</td>', 'Wow.  Is this from a plane or something?', '2003-04-17 16:31:17.000000', NULL, 1),
