INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(270247, 18141, 7073, '<td valign="top">Beautiful</td>', 'Beautiful', '2003-04-18 12:14:35.000000', NULL, 1),
(270248, 18122, 7073, '<td valign="top">Great shot.... lovely up close!</td>', 'Great shot.... lovely up close!', '2003-04-18 12:18:32.000000', NULL, 1),
(270249, 18122, 5007, '<td valign="top">Beautiful detail and nice composition. Great job!</td>', 'Beautiful detail and nice composition. Great job!', '2003-04-18 12:18:54.000000', NULL, 1),
(270250, 18050, 5007, '<td valign="top">Good day for a movie! Looks like a weekend where I live... Excellent color and good composition, I really like this photo. Makes me think you sent your spouse/friend in for the movie and you sat waiting in the car with your camera! (that would be me)</td>', 'Good day for a movie! Looks like a weekend where I live... Excellent color and good composition, I really like this photo. Makes me think you sent your spouse/friend in for the movie and you sat waiting in the car with your camera! (that would be me)', '2003-04-18 12:20:31.000000', NULL, 1),
(270251, 18090, 5007, '<td valign="top">Nice shot, you got cloudy,stormy and sunny all in one picture along with cliff, sea and land.</td>', 'Nice shot, you got cloudy,stormy and sunny all in one picture along with cliff, sea and land.', '2003-04-18 12:25:07.000000', NULL, 1),
(270252, 18187, 5007, '<td valign="top">This is too dark but I am sure it was all you had to work with. Rainier is so fickle, she only shows herself to the very patient.</td>', 'This is too dark but I am sure it was all you had to work with. Rainier is so fickle, she only shows herself to the very patient.', '2003-04-18 12:26:58.000000', NULL, 1),
(270253, 17628, 7536, '<td valign="top">Nice photo. I like the contrast of the boats with the clouds in the background. Black &amp; white was a nice choice.</td>', 'Nice photo. I like the contrast of the boats with the clouds in the background. Black & white was a nice choice.', '2003-04-18 12:30:16.000000', NULL, 1),
(270254, 18265, 5007, '<td valign="top">Beautiful macro shot!</td>', 'Beautiful macro shot!', '2003-04-18 12:31:01.000000', NULL, 1),
(270256, 17977, 7536, '<td valign="top">Nice contrast of colors. Very well done.</td>', 'Nice contrast of colors. Very well done.', '2003-04-18 12:32:56.000000', NULL, 1),
(270257, 17623, 5007, '<td valign="top">Very nice macro!</td>', 'Very nice macro!', '2003-04-18 12:33:34.000000', NULL, 1),
(270258, 17719, 7536, '<td valign="top">Nice shot. I like the change in angle. So many that I''ve seen are at 90 degrees with the flag straight across.</td>', 'Nice shot. I like the change in angle. So many that I''ve seen are at 90 degrees with the flag straight across.', '2003-04-18 12:33:46.000000', NULL, 1),
(270259, 18187, 7536, '<td valign="top">Nice shot but the details seem washed out. Maybe changing the white balance would bring out the snow of the mountain and make the clouds a little more dramatic.</td>', 'Nice shot but the details seem washed out. Maybe changing the white balance would bring out the snow of the mountain and make the clouds a little more dramatic.', '2003-04-18 12:34:42.000000', NULL, 1),
(270260, 17601, 7536, '<td valign="top">Nicely done. There is a good balance of color and a soft overall feel to it.</td>', 'Nicely done. There is a good balance of color and a soft overall feel to it.', '2003-04-18 12:35:37.000000', NULL, 1),
(270262, 17962, 7536, '<td valign="top">Interesting and original idea. Nice shapr focus and good croppping.</td>', 'Interesting and original idea. Nice shapr focus and good croppping.', '2003-04-18 12:37:12.000000', NULL, 1),
(270263, 18076, 7536, '<td valign="top">Nice photo. The lighting is just right to make the clouds look really menacing.</td>', 'Nice photo. The lighting is just right to make the clouds look really menacing.', '2003-04-18 12:37:55.000000', NULL, 1),
