(271112, 18227, 6597, '<td valign="top">good texture</td>', 'good texture', '2003-04-19 22:38:37.000000', NULL, 1),
(271113, 17707, 6325, '<td valign="top">Very well done. BW was a good choice. The man in the parking lot hunched over against the rain is a great touch.</td>', 'Very well done. BW was a good choice. The man in the parking lot hunched over against the rain is a great touch.', '2003-04-19 22:40:07.000000', NULL, 1),
(271115, 18188, 6325, '<td valign="top">LOL. Good execution and composition.</td>', 'LOL. Good execution and composition.', '2003-04-19 22:43:05.000000', NULL, 1),
(271118, 18244, 6325, '<td valign="top">Quite a ride.</td>', 'Quite a ride.', '2003-04-19 22:56:34.000000', NULL, 1),
