(271210, 18140, 6325, '<td valign="top">Captured fog very well.</td>', 'Captured fog very well.', '2003-04-20 01:18:16.000000', NULL, 1),
(271212, 18201, 6172, '<td valign="top">This could be the winner here...   If not for the physical weather, for the political.</td>', 'This could be the winner here...   If not for the physical weather, for the political.', '2003-04-20 01:18:57.000000', NULL, 1),
(271214, 17956, 7706, '<td valign="top">beautiful...</td>', 'beautiful...', '2003-04-20 01:23:07.000000', NULL, 1),
