(271578, 17632, 6771, '<td valign="top">Spectacular colors and depth.   I have no critique, except, AWESOME!   I do love the jet landing and the tower.  Very subtle</td>', 'Spectacular colors and depth.   I have no critique, except, AWESOME!   I do love the jet landing and the tower.  Very subtle', '2003-04-20 20:13:09.000000', NULL, 1),
(271579, 18213, 6771, '<td valign="top">Excellent!  Great DOF and capturing the white of the ice and snow<br/></td>', 'Excellent!  Great DOF and capturing the white of the ice and snow', '2003-04-20 20:13:52.000000', NULL, 1),
(271580, 17625, 1031, '<td valign="top">Well-controlled exposure...worth waiting around for.</td>', 'Well-controlled exposure...worth waiting around for.', '2003-04-20 20:14:33.000000', NULL, 1),
(271581, 18055, 6771, '<td valign="top">Excellent color, DOF and focus.  like to see the flower a touch more in focus, but this is superb.</td>', 'Excellent color, DOF and focus.  like to see the flower a touch more in focus, but this is superb.', '2003-04-20 20:16:32.000000', NULL, 1),
